mapper.select:
select , ct.name as logisticsChannelName, bt.name as logisticsPlatformName from logistics_order t left join logistics_channel ct on t.logistics_channel_id = ct.id and ct.is_deleted = FALSE left join dict_basic bt on t.logistics_platform = bt.code and bt.is_deleted = FALSE and bt."type" = 'logisticsPlatform' where ${params.sqlMap.default} and t.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.create_time DESC

SELECT status AS tabFlag, count(*) AS count FROM logistics_order WHERE is_deleted = FALSE
${params.permissionSql}
GROUP BY status

select t.id, t.after_sale_id as afterSaleId, t.code, t.status, t.label_status as labelStatus, t.source_code as sourceCode, t.logistics_platform as logisticsPlatform, t.logistics_channel_id as logisticsChannelId, t.track_no as trackNo, t.transport_no as transportNo, ct.name as logisticsChannelName, bt.name as logisticsPlatformName, t.exception_type as exceptionType, t.exception_reason as exceptionReason from logistics_order t left join logistics_channel ct on t.logistics_channel_id = ct.id and ct.is_deleted = FALSE left join dict_basic bt on t.logistics_platform = bt.code and bt.is_deleted = FALSE and bt."type" = 'logisticsPlatform' where t.is_deleted = FALSE
and t.id in
#{id}
